const base: LocalPlayRequest = { schema_version:'1.2',request_id:'合成请求',route:'roon_audio_input',source_kind:'local_file',local_track_id:'合成曲目',asset_id:'合成资产',expected_asset_revision:'9007199254740993',target:{core_id:'合成Core',zone_id:'合成Zone'},action:'PLAY_NOW' };
test('MBRS002 B3公开合同：原154九字段向量闭集，十进制0与大于u64边界保持pack结构', () => {
  for (const vector of vectors) assert.equal(isLocalPlayRequest(vector.publicRequest),vector.expectedStructureValid,vector.id);
  for (const revision of ['0','9007199254740993','18446744073709551616','99999999999999999999']) assert.equal(isLocalPlayRequest({...base,expected_asset_revision:revision}),true);
  for (const revision of ['', '01', '-1', '1.0', '100000000000000000000', 1, null]) assert.equal(isLocalPlayRequest({...base,expected_asset_revision:revision}),false);
  // 原无m pattern的LF/CR负控制；root独立Node22 probe已拒绝，不记候选漏洞或B3 RED。
  for(const revision of ['1\n','1\r']){assert.equal(isLocalPlayDecimal(revision),false);assert.equal(isLocalPlayRequest({...base,expected_asset_revision:revision}),false);}
  assert.equal(isLocalPlayRequest({...base,request_id:'𠮷'.repeat(256)}),true);
  assert.equal(isLocalPlayRequest({...base,request_id:'𠮷'.repeat(257)}),false);
  for (const action of ['PLAY_NOW','APPEND_MB_QUEUE','PLAY_NEXT_MB_QUEUE']) assert.equal(isLocalPlayRequest({...base,action}),true);
});
test('MBRS002 B3内部意图：只验证原pack结构，公开入口拒代际attempt和segment注入', () => {
  const intent = {...base,intent_generation:'99999999999999999999',attempt_id:'合成attempt',segment:{segment_id:'合成segment',start_frame:'0',end_frame_exclusive:'18446744073709551616',timebase_hz:48000},selection_revision:'0',autoplay_after_restart:false};
  assert.equal(isLocalPlaybackIntent(intent),true); assert.equal(isLocalPlayRequest(intent),false);
  assert.equal(isLocalPlaybackIntent({...intent,segment:null}),true);
  for (const bad of [{...intent,autoplay_after_restart:true},{...intent,session_id:'合成'}, {...intent,segment:{...intent.segment,timebase_hz:0}}, {...intent,intent_generation:'01'}, {...intent,segment:{...intent.segment,url:'http://合成.invalid'}}]) assert.equal(isLocalPlaybackIntent(bad),false);
  const request = {version:1,id:randomUUID(),command:'localCatalog.prepare',payload:intent,expectedDatasetId:randomUUID()};
  assert.equal(validateIpcRequest(request).ok,false); assert.equal(validateIpcInternalRequest(request).ok,false);
});
test('MBRS002 B3 prepare合同：原scope信封与unsupported闭集，不能进入Main可重放命令或公开prepared', () => {
  const datasetId=randomUUID(), request={version:1,id:randomUUID(),command:'localCatalog.prepare',payload:base,expectedDatasetId:datasetId};
  assert.equal(validateIpcRequest(request).ok,true); assert.equal(LOCAL_CATALOG_COMMANDS.length,22); assert.equal(LOCAL_CATALOG_INTERNAL_COMMANDS.length,6);
  for (const bad of [{...request,expectedDatasetId:undefined},{...request,expectedDatasetId:'错误'}, {...request,readContext:{}}, {...request,payload:{...base,path:'合成位置'}}, {...request,trusted:true}]) assert.equal(validateIpcRequest(bad).ok,false);
  assert.equal(isCommandOutboxExecute({commandId:randomUUID(),datasetId,command:'localCatalog.prepare',payload:base}),false);
  const unsupported={status:'unsupported',reason:'TARGET_AUTHORITY_UNAVAILABLE'};
  assert.equal(isLocalSourceUnsupported(unsupported),true);
  const response={version:1,id:request.id,ok:true,result:unsupported};
  assert.equal(validateIpcResponseForCommand(response,'localCatalog.prepare').ok,true);
  for (const result of [{status:'prepared_descriptor'},{...unsupported,relative:'合成私有位置'},{status:'Playing'},{...unsupported,session_id:'合成'}]) assert.equal(validateIpcResponseForCommand({...response,result},'localCatalog.prepare').ok,false);
});
